update.foreach:
UPDATE ${tableName}
SET goodsInventory = #{factory.goodsInventory}, rawInventory = #{factory.rawInventory}
WHERE id = #{factory.id}

mapper.select:
SELECT *
FROM ${tableName}
WHERE rawInventory < totalInventory * 0.4
  AND (rawInventory+goodsInventory) < totalInventory * 0.8
ORDER BY (rawInventory+goodsInventory) / totalInventory ASC;
